# -*- coding: utf-8 -*-
import base64
import zlib
import sys
import os

_data = ""

def run():
    try:
        script_dir = os.path.dirname(os.path.abspath(__file__))
        if script_dir not in sys.path:
            sys.path.insert(0, script_dir)
        os.chdir(script_dir)
        
        # 6단계: base64 디코딩 → XOR 복호화
        xor_key = bytes([0x5A, 0x3C, 0x7E, 0x1D, 0x9F, 0x4B, 0x6C, 0x8A])
        step0 = base64.b64decode(_data)
        decoded = bytearray()
        for i, c in enumerate(step0):
            decoded.append(c ^ xor_key[i % len(xor_key)])
        
        # 5단계: base64 디코딩
        step1 = base64.b64decode(bytes(decoded))
        
        # 4단계: zlib 압축 해제
        step2 = zlib.decompress(step1)
        
        # 3단계: base64 디코딩
        step3 = base64.b64decode(step2)
        
        # 2단계: zlib 압축 해제
        source = zlib.decompress(step3).decode('utf-8')
        
        # 실행
        exec(source, {
            "__name__": "__main__",
            "__file__": os.path.join(script_dir, "kakaotalk.py"),
            "__builtins__": __builtins__,
        })
    except Exception as e:
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    run()
